const sorted=a=>[...new Set((a||[]).map(Number))].sort((x,y)=>x-y);
const equal=(a,b)=>JSON.stringify(sorted(a))===JSON.stringify(sorted(b));
async function api(page,method,path,body){return page.evaluate(async x=>{const o={method:x.method,headers:{Accept:'application/json'},credentials:'same-origin'};if(x.body!==undefined){o.headers['Content-Type']='application/json';o.body=JSON.stringify(x.body)}const r=await fetch(x.path,o);let p={};try{p=await r.json()}catch(e){}return{status:r.status,payload:p,url:r.url}}, {method,path:base+path,body})}
async function snapshot(page){const r=await api(page,'GET','/company/roles-access/data');must(r.status===200&&r.payload.ok===true,'snapshot failed');return r.payload}
async function matrix(page){const s=await snapshot(page),ps=[];for(const m of s.memberships){const r=await api(page,'GET','/company/roles-access/assignments?membership_id='+Number(m.id));must(r.status===200&&r.payload.success===true,'matrix failed '+m.id);ps.push(r.payload)}return{s,payloads:ps}}
function setFrom(mx,type,id){const ids=[];for(const p of mx.payloads){const e=((p.entities||{})[type]||[]).find(x=>Number(x.id)===Number(id));if(e&&e.assigned)ids.push(Number(p.selected_membership_id))}return sorted(ids)}
async function backendSet(page,type,id){return setFrom(await matrix(page),type,id)}
async function assignmentPost(page,type,id,ids){const r=await api(page,'POST','/company/responsible-assignments/reassign',{entity_type:type,entity_id:Number(id),membership_ids:sorted(ids)});must(r.status===200&&r.payload.success===true,`${type}:${id} POST failed ${r.status}`);return sorted(r.payload.membership_ids)}
async function restore(page,type,id,before){for(let i=0;i<3;i++){try{await assignmentPost(page,type,id,before);if(equal(await backendSet(page,type,id),before))return}catch(e){}await page.waitForTimeout(150)}throw new Error(`RESTORE FAILED ${type}:${id}`)}
async function waitAssignments(page){await page.locator('[data-access-tab="assignments"]').click();for(let i=0;i<160;i++){if(await page.locator('[data-assignment-group]').count()===4)return;await page.waitForTimeout(100)}throw new Error('assignment panels did not load')}
async function waitCheckbox(box){for(let i=0;i<160;i++){if(!(await box.isDisabled()))return;await new Promise(r=>setTimeout(r,50))}throw new Error('checkbox stuck')}
